import {mountFigure} from './figure-effects.js';
import {readingLessons,readingSources} from './reading-data.js';
import {mean,boxStats,distributions,sampleRows,volcanoGenes,volcanoPass,heatRows,zscore,pcaData,cells,markers,groupNames,markerStats,spatialBins,enrichment} from './reading-lab.js';
const colors=['#558fc5','#d28380','#67a58a'];
const table=(head,rows)=>`<div class="integration-table"><table><thead><tr>${head.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const svg=(body,label)=>`<svg class="reading-chart" viewBox="0 0 540 310" role="group" aria-label="${label}">${body}</svg>`;
const axes=(x,y)=>`<path d="M60 30V260H510" fill="none" stroke="#9eacb6"/><text x="285" y="299" text-anchor="middle">${x}</text><text x="17" y="145" transform="rotate(-90 17 145)" text-anchor="middle">${y}</text>`;
const tick=(x,y,t)=>`<text x="${x}" y="${y}" text-anchor="middle">${t}</text>`;
const pick=(id,label)=>`data-reading-pick="${id}" tabindex="0" role="button" aria-label="${label}"`;
const point=(id,x,y,color,label,r=7)=>`<circle ${pick(id,label)} cx="${x}" cy="${y}" r="${r}" fill="${color}" stroke="#fff" stroke-width="1.5"><title>${label}</title></circle>`;
const tabs=(key,value,options)=>`<div class="integration-switch">${options.map((o,i)=>`<button data-reading-choice="${key}" data-value="${i}" aria-pressed="${value===i}">${o}</button>`).join('')}</div>`;
const slider=(key,value,label,min,max,step=1)=>`<label class="integration-slider">${label}<output>${value}</output><input data-reading-control="${key}" aria-label="${label}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
const shade=(v,max=8)=>`hsl(207 52% ${96-Math.min(1,Math.max(0,v/max))*48}%)`;
const zcolor=v=>v>=0?`hsl(13 52% ${95-Math.min(v/2,1)*38}%)`:`hsl(207 52% ${95-Math.min(-v/2,1)*38}%)`;
const source=l=>`<a href="${readingSources[l.source].url}" target="_blank" rel="noopener noreferrer">${readingSources[l.source].label} ↗</a>`;
export function readingReader(l){return `<div class="reader-heading"><span class="eyebrow">READ THE FIGURE / ${l.scene}</span><h2>${l.name}</h2><p class="lesson-goal"><strong>学完你能：</strong>${l.goal}</p></div><div class="lesson-analogy"><span>带着一个问题看图</span><p>${l.challenge}</p><p>本章图形和数值均为原创教学模拟，参考链接用于继续学习方法，并非原论文或教程的数据复现。</p></div><div class="lesson-sections">${l.steps.map(([title,body,takeaway],i)=>`<section><span class="lesson-number">0${i+1}</span><div><h3>${title}</h3><p>${body}</p><p><strong>读图判断：</strong>${takeaway}</p></div></section>`).join('')}</div><div class="lesson-terms">${l.terms.map(([cn,en])=>`<span><strong>${cn}</strong><small>${en}</small></span>`).join('')}</div><div class="integration-source">继续阅读：${source(l)}</div><div class="reader-actions"><button class="outline" data-mode="process">打开交互图表 ↑</button><button class="primary" data-practice>完成本课 4 道练习 →</button></div>`;}
export class ReadingStudio{
 constructor(root,lesson,mode){this.root=root;this.lesson=lesson;this.mode=mode;this.step=0;this.selected=null;this.timer=null;this.values=this.defaults();this.abort=new AbortController();root.addEventListener('click',e=>this.click(e),{signal:this.abort.signal});root.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-reading-pick]')){e.preventDefault();this.selected=e.target.dataset.readingPick;this.updateSelection();}},{signal:this.abort.signal});root.addEventListener('input',e=>{const k=e.target.dataset.readingControl;if(!k)return;this.values[k]=+e.target.value;e.target.previousElementSibling.value=e.target.value;this.draw();},{signal:this.abort.signal});this.render();}
 defaults(){return {collapse:0,fc:1,p:.05,distribution:0,z:0,batch:0,color:0,cellColor:0,threshold:0,coarse:0,gene:0,scale:0,enrich:0};}
 destroy(){this.pause();this.abort.abort();}
 pause(){clearInterval(this.timer);this.timer=null;}
 getState(){return {topic:this.lesson.id,mode:this.mode,step:this.step,playing:!!this.timer,selected:this.selected,values:{...this.values}};}
 click(e){const el=e.target.closest('[data-reading-pick],button');if(!el)return;if(el.dataset.readingPick){this.selected=el.dataset.readingPick;this.updateSelection();}if(el.dataset.readingChoice){this.values[el.dataset.readingChoice]=+el.dataset.value;this.selected=null;this.render();}if(el.dataset.readingStep!==undefined){this.step=+el.dataset.readingStep;this.pause();this.render();}if(el.dataset.readingPlay!==undefined){if(this.timer)this.pause();else{if(this.step===3)this.step=0;this.timer=setInterval(()=>{this.step++;if(this.step===3)this.pause();this.render();},6000);}this.render();}if(el.dataset.readingReset!==undefined){this.values=this.defaults();this.selected=null;this.render();}}
 render(){const l=this.lesson;this.root.innerHTML=`<div class="integration-studio reading-studio"><header><span class="eyebrow">${l.scene} / FIGURE LAB</span><h2>${l.name}</h2><p class="reading-goal">${l.goal}</p><span class="integration-badge">教学模拟 · 可点击图中数据</span></header>${this.mode==='connections'?this.checklist():`${this.mode==='structure'?this.guide():`<div class="integration-controls">${this.controls()}<button class="outline" data-reading-reset>重置图表</button></div>`}<div data-reading-plot></div><p class="reading-selection" data-reading-selection aria-live="polite"></p><details class="reading-raw"><summary>查看对应的数据与计算说明</summary><div data-reading-table></div></details>`}</div>`;if(this.mode!=='connections')this.draw();}
 guide(){const s=this.lesson.steps[this.step];return `<div class="reading-steps">${this.lesson.steps.map((s,i)=>`<button data-reading-step="${i}" aria-pressed="${i===this.step}"><b>0${i+1}</b>${s[0]}</button>`).join('')}</div><div class="reading-guide"><strong>${s[0]}</strong><p>${s[1]}</p><small>${s[2]}</small></div><div class="reading-guide-actions"><button class="outline" data-reading-play>${this.timer?'暂停讲解':'自动讲解 · 每步 6 秒'}</button><button class="outline" data-mode="process">动手改变这张图 →</button></div>`;}
 controls(){const v=this.values;switch(this.lesson.id){case'replicates':return tabs('collapse',v.collapse,['每次测量','供者均值']);case'volcano':return slider('fc',v.fc,'最小 |log₂FC|',0,3,.2)+slider('p',v.p,'最大 padj',.001,.1,.001);case'read-distribution':return tabs('distribution',v.distribution,['均值柱图','箱线 + 散点','小提琴 + 散点']);case'read-heatmap':return tabs('z',v.z,['处理值','按行 Z 分数']);case'read-pca':return slider('batch',v.batch,'模拟批次效应',0,8,.5)+tabs('color',v.color,['按分组着色','按批次着色']);case'singlecell':return tabs('cellColor',v.cellColor,['候选类型','批次','MS4A1','LST1']);case'read-markers':return slider('threshold',v.threshold,'检测阈值（表达 > 阈值）',0,7);case'spatial':return tabs('gene',v.gene,['Gene A','Gene B'])+tabs('coarse',v.coarse,['小采样区','2×2 合并区'])+tabs('scale',v.scale,['固定色标 0—8','当前图自动色标']);case'read-enrichment':return tabs('enrich',v.enrich,['成员集中左端','成员均匀分布','成员集中右端']);}}
 draw(){const host=this.root.querySelector('[data-reading-plot]');if(!host)return;const v=this.values;let chart='',legend='',insight='',rows=[],headers=[],note='';this.descriptions={};const describe=(id,text)=>this.descriptions[id]=text;
 switch(this.lesson.id){
 case'replicates':{const data=sampleRows(!!v.collapse);chart=svg(axes('分组','处理后的表达值（任意单位）')+[0,2,4,6,8].map(t=>tick(43,264-t*26,t)).join('')+data.map((r,i)=>{const donor=+r.donor.slice(1)-1,x=170+r.group*200+(donor%3-1)*35+(v.collapse?0:(i%2?6:-6)),y=260-r.value*26;describe(r.id,`${r.id} · ${r.donor} · ${r.group?'处理':'对照'} · 值 ${r.value.toFixed(1)}。独立供者共 6 位。`);return point(r.id,x,y,colors[r.group],r.id);}).join('')+tick(170,280,'对照')+tick(370,280,'处理'),'供者与测量散点图');if(!v.collapse){chart=chart.replace('</svg>',[0,1,2,3,4,5].map(i=>{const x=170+(i<3?0:200)+(i%3-1)*35,base=i+2;return `<path d="M${x-6} ${260-(base-.2)*26}L${x+6} ${260-(base+.2)*26}" stroke="#8b99a1" pointer-events="none"/>`;}).join('')+'</svg>');}legend='湖蓝：对照 · 珊瑚粉：处理 · 连线：同供者的两次测量';insight=`显示 ${data.length} 个点，但始终是 6 位独立供者，每组 3 位。`;headers=['点 ID','供者','组别','值'];rows=data.map(r=>[r.id,r.donor,r.group?'处理':'对照',r.value.toFixed(1)]);note='技术重复均值为算术平均；图中未计算 P 值。';break;}
 case'volcano':{const count=volcanoGenes.filter(g=>volcanoPass(g,v.fc,v.p)).length;chart=svg(axes('log₂（处理 / 对照）','−log₁₀(padj)')+[-3,-2,-1,0,1,2,3].map(t=>tick(285+t*70,280,t)).join('')+[0,1,2,3,4].map(t=>tick(42,264-t*53,t)).join('')+`<path d="M${285-v.fc*70} 30V260M${285+v.fc*70} 30V260M60 ${260+Math.log10(v.p)*53}H510" stroke="#a4aeb7" stroke-dasharray="5 5" fill="none"/>`+volcanoGenes.map(g=>{describe(g.id,`${g.id}：log₂FC ${g.fc}，处理/对照 = ${(2**g.fc).toFixed(2)} 倍，padj ${g.padj}；${volcanoPass(g,v.fc,v.p)?'满足':'不满足'}当前双阈值。`);return point(g.id,285+g.fc*70,260+Math.log10(g.padj)*53,volcanoPass(g,v.fc,v.p)?(g.fc>0?colors[1]:colors[0]):'#ccd2d6',g.id);}).join(''),'可调整阈值的火山图');legend='珊瑚粉：处理升高 · 湖蓝：处理降低 · 浅灰：未同时通过阈值';insight=`当前 ${count} / ${volcanoGenes.length} 个基因满足 |log₂FC| ≥ ${v.fc} 且 padj ≤ ${v.p}。`;headers=['基因','log₂FC','padj','当前通过'];rows=volcanoGenes.map(g=>[g.id,g.fc,g.padj,volcanoPass(g,v.fc,v.p)?'是':'否']);note='FC 与 padj 均为教学预设；改变阈值只改变分类，不重新做统计检验。';break;}
 case'read-distribution':{const x=[190,390],y=n=>260-n*31;let body=axes('独立样本组','表达值（任意单位）')+[0,2,4,6].map(t=>tick(42,y(t)+4,t)).join('');distributions.forEach((a,k)=>{const stats=boxStats(a);if(v.distribution===0)body+=`<rect x="${x[k]-40}" y="${y(mean(a))}" width="80" height="${mean(a)*31}" rx="5" fill="${colors[k]}"/>`;else if(v.distribution===1)body+=`<path d="M${x[k]} ${y(stats.low)}V${y(stats.high)}" stroke="#73838e"/><rect x="${x[k]-30}" y="${y(stats.q3)}" width="60" height="${(stats.q3-stats.q1)*31}" fill="${colors[k]}" opacity=".4"/><path d="M${x[k]-30} ${y(stats.median)}h60M${x[k]-15} ${y(stats.low)}h30M${x[k]-15} ${y(stats.high)}h30" stroke="#536977"/>`;else{const levels=Array.from({length:81},(_,i)=>-1+i*.1),density=levels.map(n=>mean(a.map(t=>Math.exp(-.5*((n-t)/.6)**2)))),max=Math.max(...density),outline=levels.map((n,i)=>[x[k]+density[i]/max*45,y(n)]).concat(levels.map((n,i)=>[x[k]-density[i]/max*45,y(n)]).reverse());body+=`<path d="M${outline.map(p=>p.join(',')).join('L')}Z" fill="${colors[k]}" opacity=".4"/>`;}if(v.distribution)body+=a.map((n,i)=>{const id=`${k}-${i}`;describe(id,`组 ${k?'B':'A'}，样本 ${i+1}：${n}。该组均值 ${mean(a)}，中位数 ${stats.median}。`);return point(id,x[k]+(i-2.5)*6,y(n),colors[k],`样本 ${i+1}: ${n}`,5);}).join('');body+=tick(x[k],280,`组 ${k?'B':'A'} · n=6`);});chart=svg(body,'相同均值的不同分布');legend='每点为独立样本 · 箱体为 Q1—Q3 · 中线为中位数';insight='两组均值都为 3。展开散点后，A 集中在 2—4，B 分布在 0 与 6。';headers=['组','全部观测','均值','Q1 / 中位数 / Q3'];rows=distributions.map((a,k)=>{const s=boxStats(a);return [k?'B':'A',a.join(', '),mean(a),`${s.q1} / ${s.median} / ${s.q3}`];});note='四分位数使用线性插值；须线使用 1.5×IQR 规则。小提琴是高斯核密度示意，带宽 0.6，每组独立缩放，截取 −1 至 7；尾部不代表负值观测。';break;}
 case'read-heatmap':{const data=v.z?heatRows.map(zscore):heatRows;let body='';data.forEach((a,i)=>{body+=tick(48,68+i*48,`Gene ${'ABCD'[i]}`);a.forEach((n,j)=>{const id=`${i}-${j}`;describe(id,`Gene ${'ABCD'[i]} / S${j+1}：处理值 ${heatRows[i][j]}，行 Z = ${zscore(heatRows[i])[j].toFixed(2)}。`);body+=`<rect ${pick(id,`Gene ${'ABCD'[i]}，样本 ${j+1}`)} x="${95+j*65}" y="${40+i*48}" width="59" height="42" rx="4" fill="${v.z?zcolor(n):shade(n,120)}"/><text pointer-events="none" x="${124+j*65}" y="${66+i*48}" text-anchor="middle" fill="${v.z? '#3c505d':n>80?'#fff':'#3c505d'}">${v.z?n.toFixed(1):n}</text>`;});});body+=[1,2,3,4,5,6].map((n,i)=>tick(124+i*65,251,`S${n}`)).join('')+tick(190,278,'对照 S1—S3')+tick(385,278,'处理 S4—S6');chart=svg(body,'处理值与行标准化热图');legend=v.z?'色标：蓝 −2 → 浅色 0 → 粉 +2（行 Z）':'色标：浅色 0 → 深湖蓝 120（处理值）';insight=v.z?'现在比较每个基因相对自身均值的变化。Gene D 全部相同，本图将其 Z 设为 0。':'统一尺度可比较本教学矩阵的数值。切换行 Z 分数，寻找低数值但变化明显的 Gene B。';headers=['基因','S1','S2','S3','S4','S5','S6'];rows=data.map((a,i)=>[`Gene ${'ABCD'[i]}`,...a.map(n=>v.z?n.toFixed(2):n)]);note='Z = (值 − 行均值) / 行样本标准差；常数行显示 0。未做聚类。';break;}
 case'read-pca':{const p=pcaData(v.batch),max=Math.max(...p.rows.flatMap(r=>[Math.abs(r.x),Math.abs(r.y)]))*1.15;chart=svg(axes(`PC1（${p.variance[0].toFixed(1)}%）`,`PC2（${p.variance[1].toFixed(1)}%）`)+`<path d="M285 30V260M60 145H510" stroke="#d7dee3" stroke-dasharray="3 4"/>`+p.rows.map(r=>{describe(r.id,`${r.id} · ${r.group?'处理':'对照'} · 批次 ${r.batch?'B':'A'}；PC1 ${r.x.toFixed(2)}，PC2 ${r.y.toFixed(2)}。`);return point(r.id,285+r.x/max*210,145-r.y/max*105,colors[v.color?r.batch:r.group],r.id,9)+tick(285+r.x/max*210,130-r.y/max*105,r.id);}).join(''),'现场计算的二维 PCA');legend=v.color?'湖蓝：批次 A · 珊瑚粉：批次 B':'湖蓝：对照 · 珊瑚粉：处理';insight=`PC1 解释 ${p.variance[0].toFixed(1)}% 方差。换色只改变图例；批次效应改变输入。`;headers=['样本','分组','批次','特征 1','特征 2'];rows=p.rows.map(r=>[r.id,r.group?'处理':'对照',r.batch?'B':'A',...r.features.map(n=>n.toFixed(1))]);note=`对两列中心化，未按列缩放，特征单位相同。用协方差矩阵求主轴；PC1 载荷 = (${p.loading.map(n=>n.toFixed(3)).join(', ')})。PCA 轴符号可整体翻转，不改变含义。`;break;}
 case'singlecell':{chart=svg(axes('UMAP 1（示意坐标）','UMAP 2（示意坐标）')+cells.map(c=>{describe(c.id,`${c.id} · ${groupNames[c.group]}（预设）· 批次 ${c.batch?'B':'A'}；CD3D ${c.expr[0]} / MS4A1 ${c.expr[1]} / LST1 ${c.expr[2]}。`);const color=v.cellColor===0?colors[c.group]:v.cellColor===1?colors[c.batch]:shade(c.expr[v.cellColor===2?1:2]);return point(c.id,c.x,c.y,color,c.id,7);}).join(''),'可切换着色的单细胞嵌入示意');legend=v.cellColor===0?'湖蓝：候选 T · 珊瑚粉：候选 B · 青绿：候选髓系':v.cellColor===1?'湖蓝：批次 A · 珊瑚粉：批次 B':'表达色标：浅色 0 → 深湖蓝 8';insight='切换图例时细胞坐标保持不变。候选身份需要结合标记和背景，岛间距离不是发育时间。';headers=['细胞','预设群','批次',...markers];rows=cells.map(c=>[c.id,groupNames[c.group],c.batch?'B':'A',...c.expr]);note='36 个虚构细胞与手工构建的嵌入形态；未运行 UMAP、聚类或真实 PBMC 数据分析。';break;}
 case'read-markers':{const stats=markerStats(v.threshold);chart=svg(stats.map(r=>{describe(r.id,`${groupNames[r.group]} / ${r.gene}：全部细胞平均 ${r.avg.toFixed(2)}，表达 > ${v.threshold} 的细胞占 ${r.percent.toFixed(1)}%。`);const x=210+markers.indexOf(r.gene)*115,y=65+r.group*75;return `<circle ${pick(r.id,`${groupNames[r.group]} ${r.gene}`)} cx="${x}" cy="${y}" r="24" fill="transparent" stroke="none"/><circle pointer-events="none" cx="${x}" cy="${y}" r="${Math.sqrt(r.percent/100)*24}" fill="${shade(r.avg)}"/>`;}).join('')+groupNames.map((name,i)=>tick(75,70+i*75,name)).join('')+markers.map((name,i)=>tick(210+i*115,270,name)).join(''),'标记平均值与阳性比例气泡图');legend='面积：表达比例 0—100%（空位为 0%） · 颜色：全群均值 0—8';insight='本图阈值只改变阳性比例，不改变用于着色的全群均值。点击任一位置可查看两种数值。';headers=['预设群','标记','全部细胞均值','阳性比例'];rows=stats.map(r=>[groupNames[r.group],r.gene,r.avg.toFixed(2),r.percent.toFixed(1)+'%']);note='面积正比于比例，因此半径正比于比例的平方根；每群 12 个虚构细胞。';break;}
 case'spatial':{const bins=spatialBins(!!v.coarse,v.gene),min=v.scale?Math.min(...bins.map(b=>b.value)):0,max=v.scale?Math.max(...bins.map(b=>b.value)):8;chart=svg(`<path d="M70 50Q270 0 490 45L505 240Q280 300 65 250Z" fill="#eee7e3"/><text x="270" y="22" text-anchor="middle">虚构组织轮廓 · 网格单位，非组织照片</text>`+bins.map(b=>{describe(b.id,`采样区 (${b.x}, ${b.y}) · ${b.size}×${b.size} 网格 · Gene ${v.gene?'B':'A'} 均值 ${b.value.toFixed(2)}。采样区可能含多个细胞。`);return `<rect ${pick(b.id,`采样区 ${b.id}`)} x="${85+b.x*50}" y="${40+b.y*36}" width="${b.size*50-3}" height="${b.size*36-3}" rx="4" fill="${shade(b.value-min,max-min)}" stroke="#fff"/>`;}).join('')+tick(280,290,'左 → 右：网格 x；上 → 下：网格 y'),'不同分辨率的空间表达图');legend=`色标：浅色 ${min.toFixed(1)} → 深湖蓝 ${max.toFixed(1)} · ${v.scale?'当前图自动范围':'固定范围'}`;insight=`当前 ${bins.length} 个采样区。${v.coarse?'大区平均了四个小区的信号。':'每个区也可能含多个细胞。'} 比较不同图时，先统一色标。`;headers=['区 ID','覆盖网格','均值'];rows=bins.map(b=>[b.id,`${b.size}×${b.size}`,b.value.toFixed(2)]);note='聚合是等权算术平均的分辨率示意；未执行平台特定的计数标准化、分割或去卷积。';break;}
 case'read-enrichment':{const e=enrichment(v.enrich);chart=svg(axes('基因排序：处理侧 ← 排名 → 对照侧','运行富集分数')+`<path d="M60 145H510" stroke="#b5c1c8" stroke-dasharray="4 4"/><path d="${e.points.map((n,i)=>`${i?'L':'M'}${60+i*22.5},${145-n*100}`).join(' ')}" fill="none" stroke="#55a18c" stroke-width="3"/>`+e.points.slice(1).map((n,i)=>{describe(`R${i+1}`,`第 ${i+1} 位，${e.hits.includes(i)?'是':'不是'}集合成员；运行分数 ${n.toFixed(3)}。`);return point(`R${i+1}`,60+(i+1)*22.5,145-n*100,'#55a18c',`排名 ${i+1}`,4);}).join('')+e.hits.map(i=>`<path d="M${60+(i+1)*22.5} 249v10" stroke="#687d72" stroke-width="3"/>`).join('')+[-1,0,1].map(n=>tick(40,149-n*100,n)).join('')+[1,5,10,15,20].map(n=>tick(60+n*22.5,280,n)).join(''),'经典未加权基因集富集曲线');legend='绿线：运行分数 · 底部刻线：集合成员 · 灰虚线：0';insight=`经典 ES = ${e.es.toFixed(3)}。相同的 4 个成员占据不同排名，可产生不同方向与幅度。`;headers=['排名','集合成员','运行分数'];rows=e.points.slice(1).map((n,i)=>[i+1,e.hits.includes(i)?'是':'否',n.toFixed(3)]);note='命中 +1/4，未命中 −1/16；ES 取绝对值最大的带符号偏离。本示意不计算置换 P 值、NES 或 FDR。';break;}}
 mountFigure(host,chart+`<p class="reading-legend">${legend}</p><p class="integration-insight">${insight}</p>`);this.root.querySelector('[data-reading-table]').innerHTML=table(headers,rows)+`<p class="integration-note">${note}</p>`;this.updateSelection();}
 updateSelection(){const selected=this.root.querySelector('[data-reading-selection]');if(!selected)return;selected.textContent=this.descriptions[this.selected]||'点击图中数据查看详情；键盘可用 Tab 选中后按 Enter。';this.root.querySelectorAll('[data-reading-pick]').forEach(el=>el.classList.toggle('reading-picked',el.dataset.readingPick===this.selected));}
 checklist(){return `<div class="reading-checklist"><h3>读任何一张图，先回答这四个问题</h3>${['每个点或格子代表什么？独立样本有多少？','坐标、单位、图例和数据变换是什么？','模式是否受分组、批次、阈值或采样影响？','这张图支持哪种结论，还需要什么验证？'].map((s,i)=>`<p><b>0${i+1}</b>${s}</p>`).join('')}</div><p class="integration-note">选择一张图继续练习，每课都有逐步引导、实验与四道题。</p><div class="reading-directory">${readingLessons.map(l=>`<button data-jump="${l.id}"><strong>${l.name}</strong><small>${l.goal}</small></button>`).join('')}</div><div class="integration-source">本课参考：${source(this.lesson)}</div>`;}
}
